SELECT 'gongkao', '先捆后插', 'kp-pc-bg-bind-gap', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "先捆后插综合法"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目同时包含“A和B相邻”以及“C和D不相邻”的双重限制。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲乙必须相邻，同时丙丁不能相邻”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[第一步绝对是处理相邻限制: 用捆绑法把甲乙包好] --> B[把大包和其他无限制元素排成一队(含大包内部小排列)]\nB --> C[在排好的这队里找出所有空隙]\nC --> D[第二步处理不相邻限制: 把丙丁插进这些空隙里]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "顺序搞反：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "一定要【先捆绑、再排队、最后插空】。如果先插空再捆绑，会彻底打乱队伍的空隙数量。"}]}]}]}$$ AS jsonb), NULL, '先捆后插的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "先捆后插"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_bg_bind_gap", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
